from collections import deque


class SlidingWindowLog:
    """Remembers when one caller's recent requests happened."""

    def __init__(self, window_seconds):
        self.window = window_seconds
        self._hits = deque()

    def prune(self, now):
        """Forget requests that are no longer inside the window (now - window, now]."""
        cutoff = now - self.window
        while self._hits and self._hits[0] < cutoff:
            self._hits.popleft()

    def count(self):
        return len(self._hits)

    def oldest(self):
        return self._hits[0]

    def record(self, now):
        self._hits.append(now)

