from window import SlidingWindowLog


class RateLimiter:
    def __init__(self, clock, policy):
        self.clock = clock
        self.policy = policy
        self._windows = {}

    def _window_for(self, caller_id):
        if caller_id not in self._windows:
            self._windows[caller_id] = SlidingWindowLog(self.policy.window_seconds)
        return self._windows[caller_id]

    def allow(self, caller_id):
        """True and counts the request if the caller is under the limit; False and counts nothing otherwise."""
        now = self.clock.now()
        window = self._window_for(caller_id)
        window.prune(now)
        if window.count() >= self.policy.limit:
            return False
        window.record(now)
        return True

    def retry_after(self, caller_id):
        """Seconds until this caller may try again; 0 if they can go now."""
        now = self.clock.now()
        window = self._window_for(caller_id)
        window.prune(now)
        if window.count() < self.policy.limit:
            return 0.0
        return window.oldest() + self.policy.window_seconds

