class Failing(unittest.TestCase):
    def setUp(self):
        self.clock = FakeClock()
        self.limiter = RateLimiter(self.clock, Policy(limit=3, window_seconds=10))

    def test_a_request_expires_exactly_when_the_window_ends(self):
        for _ in range(3):
            self.assertTrue(self.limiter.allow("u1"))
        self.clock.advance(10)  # the three requests are now exactly 10 seconds old
        self.assertTrue(self.limiter.allow("u1"))

    def test_retry_after_is_a_duration_not_a_time(self):
        self.clock.advance(100)
        for _ in range(3):
            self.limiter.allow("u1")
        self.clock.advance(4)
        self.assertFalse(self.limiter.allow("u1"))
        self.assertAlmostEqual(self.limiter.retry_after("u1"), 6.0)

